  getItem(key) { return key in sharedStorage ? sharedStorage[key] : null; },
  setItem(key, value) { sharedStorage[key] = String(value); },
  removeItem(key) { delete sharedStorage[key]; },
  clear() { Object.keys(sharedStorage).forEach(k => delete sharedStorage[k]); },
  get length() { return Object.keys(sharedStorage).length; },
  key(i) { return Object.keys(sharedStorage)[i] || null; },
